$nb = @(
  @{q="Số điện thoại cấp cứu y tế tại Việt Nam là số nào?"; opts=@("115","114","113","111"); c=0; ex="115 là số điện thoại cấp cứu y tế khẩn cấp tại Việt Nam."},
  @{q="Số tổng đài quốc gia bảo vệ trẻ em tại Việt Nam là gì?"; opts=@("111","115","113","114"); c=0; ex="Tổng đài 111 là đường dây nóng miễn phí bảo vệ quyền và sự an toàn của trẻ em."},
  @{q="Quy tắc an toàn đầu tiên và quan trọng nhất khi nhìn thấy người đuối nước là gì?"; opts=@("Hô hoán thật to tìm sự giúp đỡ của người lớn","Lập tức nhảy xuống bơi ra cứu","Chạy đi tìm phao cứu sinh thật xa","Tìm cách cúi sát mép nước kéo nạn nhân"); c=0; ex="Hô to để huy động người lớn và người xung quanh đến ứng cứu ngay lập tức."},
  @{q="Trong nguyên tắc cứu hộ từ bờ 'Hô - Ném - Chìa', hành động 'Ném' là ném vật gì?"; opts=@("Phao bơi, can nhựa rỗng đậy kín hoặc vật nổi","Hòn đá to để đánh dấu vị trí","Dây xích sắt nặng","Quần áo nặng"); c=0; ex="Ném các vật có khả năng nổi cao như phao, can nhựa rỗng có nắp đậy kín."},
  @{q="Trong nguyên tắc 'Hô - Ném - Chìa', hành động 'Chìa' nghĩa là chìa vật gì?"; opts=@("Cành cây, sào tre dài hoặc dây thừng từ vị trí an toàn trên bờ","Chìa bàn tay của mình khi đứng sát mép bờ trơn","Chìa một chân xuống nước để nạn nhân bám","Chìa một sợi dây ngắn 20cm"); c=0; ex="Chìa vật dài từ vị trí vững chắc trên bờ để kéo nạn nhân vào an toàn."},
  @{q="Vật dụng sinh hoạt gia đình nào sau đây có thể tận dụng làm vật nổi cứu sinh?"; opts=@("Can nhựa rỗng 5 lít có nắp đậy chặt","Bình hoa bằng gốm sứ","Nồi kim loại không nắp","Cặp sách chứa nhiều sách vở nặng"); c=0; ex="Can nhựa rỗng đậy kín nắp chứa nhiều không khí nên có sức nổi rất tốt."},
  @{q="Trang phục bảo hộ bắt buộc phải mặc khi tham gia giao thông đường thủy là gì?"; opts=@("Áo phao bơi đúng kích cỡ","Áo khoác gió dày","Áo mưa tiện lợi","Quần áo bơi bình thường"); c=0; ex="Áo phao đạt chuẩn và cài đủ dây đai an toàn."},
  @{q="Khi tắm biển, nhìn thấy cờ màu đỏ cắm trên bờ cát có nghĩa là gì?"; opts=@("Vùng nước nguy hiểm, có sóng lớn hoặc dòng chảy xa bờ, cấm bơi","Vùng nước an toàn được phép bơi tự do","Khu vực dành riêng cho trẻ em","Khu vực có nhân viên cứu hộ đang trực"); c=0; ex="Cờ đỏ là biển báo nguy hiểm cấm xuống tắm biển tại khu vực đó."},
  @{q="Hiện tượng 'dòng chảy xa bờ' (dòng Rip) ở bãi biển có đặc điểm nhận biết nào?"; opts=@("Vùng nước phẳng lặng, màu sẫm hơn, không có sóng bạc đầu","Vùng có sóng cuộn trắng xóa xô vào bờ liên tục","Vùng nước có nhiều bong bóng nổi lên từ đáy cát","Vùng nước có cát màu trắng sáng nhất"); c=0; ex="Dòng rip thường trông phẳng lặng đánh lừa thị giác, tạo thành lối nước rút mạnh ra xa bờ."},
  @{q="Khi bị rơi xuống nước mà chưa biết bơi, tư thế tự cứu nào giúp cơ thể dễ nổi nhất?"; opts=@("Thả lỏng cơ thể, ngửa đầu lên trời, hai tay dang ngang","Vùng vẫy chân tay thật mạnh liên tục","Cố gắng co người lại như quả bóng","Cúi mặt xuống nước và nín thở tuyệt đối"); c=0; ex="Tư thế nằm ngửa thả lỏng giúp tận dụng sức nổi tự nhiên của phổi."},
  @{q="Tại sao xô, chậu chứa nước trong nhà tắm cần phải đậy nắp hoặc đổ hết nước?"; opts=@("Trẻ nhỏ có thể bị ngã úp đầu vào và đuối nước dù nước rất nông","Để tránh làm bẩn nguồn nước sinh hoạt","Để tiết kiệm diện tích phòng tắm","Để tránh làm trơn sàn nhà"); c=0; ex="Trẻ nhỏ có đầu nặng, khi chúi đầu vào xô nước nông khó tự đứng dậy được."},
  @{q="Khoảng thời gian lý tưởng để khởi động làm nóng cơ thể trước khi xuống bơi là bao lâu?"; opts=@("Từ 10 đến 15 phút","Chỉ cần 30 giây","Không cần khởi động nếu trời nắng ấm","Khoảng 1 tiếng đồng hồ"); c=0; ex="Khởi động từ 10-15 phút giúp cơ bắp linh hoạt, tránh chuột rút và co cơ đột ngột."},
  @{q="Hiện tượng chuột rút (vọp bẻ) khi bơi là tình trạng gì của cơ thể?"; opts=@("Sự co thắt cơ đột ngột, ngoài ý muốn và gây đau đớn dữ dội","Hiện tượng xương khớp bị trật khỏi khớp","Hiện tượng nước tràn vào tai gây chóng mặt","Hiện tượng dị ứng với nước lạnh"); c=0; ex="Chuột rút là sự co cứng cơ đột ngột do lạnh hoặc vận động quá sức."},
  @{q="Khi bơi ở hồ bơi nhân tạo, biển báo độ sâu '1.8m' có ý nghĩa gì?"; opts=@("Mực nước sâu 1 mét 80 centimet tính từ đáy lên mặt nước","Chiều dài của hồ bơi là 1 mét 80","Khu vực này chỉ dành cho người cao 1 mét 80","Khoảng cách từ mép hồ đến phao cứu sinh là 1 mét 80"); c=0; ex="Biển báo ghi chiều sâu thực tế của cột nước tại vị trí đó."},
  @{q="Sau khi ăn no, tại sao không nên xuống nước bơi lội ngay?"; opts=@("Dễ bị đau dạ dày, khó tiêu, nôn ói và tăng nguy cơ chuột rút","Làm nước hồ bơi bị đục và bẩn","Khiến cơ thể bị tăng cân nhanh hơn","Không thể nổi lên mặt nước được"); c=0; ex="Dạ dày đang cần nhiều máu để tiêu hóa thức ăn, vận động mạnh dễ gây trào ngược và co cơ."},
  @{q="Loại áo phao nào sau đây được coi là đạt tiêu chuẩn an toàn?"; opts=@("Áo phao có các khóa cài chắc chắn, còi cứu hộ và vừa vặn cơ thể","Áo phao thổi hơi bằng miệng mỏng manh","Áo phao quá rộng so với người mặc","Áo phao bị rách khóa nhưng có màu sặc sỡ"); c=0; ex="Áo phao đạt chuẩn làm từ mút xốp chuyên dụng, đầy đủ khóa cài đai bụng và đùi."},
  @{q="Vùng nước ở khúc quanh của dòng sông thường có đặc điểm nguy hiểm gì?"; opts=@("Bên lở có dòng chảy xiết và xoáy ngầm sâu bất ngờ","Nước luôn luôn nông và có cát mịn","Dòng nước hoàn toàn đứng yên","Không bao giờ có sóng ngầm"); c=0; ex="Khúc sông cong thường bị xói mòn tạo hố sâu và dòng xoáy nguy hiểm bên bờ lở."},
  @{q="Khi đi thuyền tham quan trên hồ, hành động nào sau đây là an toàn?"; opts=@("Ngồi yên tại vị trí quy định và mặc áo phao suốt chuyến đi","Đứng lên mép thuyền chụp ảnh tự sướng","Thò chân tay xuống nước đùa nghịch khi thuyền chạy","Nhảy múa cùng bạn bè để tạo không khí vui vẻ"); c=0; ex="Ngồi đúng vị trí giúp thuyền giữ thăng bằng và áo phao bảo vệ tính mạng."},
  @{q="Biển báo hình tròn viền đỏ, có hình người bơi bị gạch chéo có ý nghĩa gì?"; opts=@("Cấm tắm, cấm bơi lội tại khu vực này","Khu vực bơi có thu phí","Cho phép bơi nhưng phải mặc áo phao","Khu vực chỉ dành cho vận động viên bơi lội"); c=0; ex="Biển báo cấm tắm để cảnh báo nguy hiểm khôn lường dưới lòng nước."},
  @{q="Khi gặp trời mưa to, sấm chớp khi đang bơi dưới nước, hành vi đúng đắn là gì?"; opts=@("Lập tức lên bờ, tìm nơi trú ẩn an toàn và tránh xa các cột sắt, gốc cây cao","Tiếp tục bơi vì nước mưa làm hồ mát mẻ hơn","Lặn sâu xuống nước để tránh sấm sét","Bám vào phao sắt giữa hồ chờ tạnh mưa"); c=0; ex="Nước dẫn điện cực tốt, ở dưới nước khi có sấm sét có nguy cơ bị sét đánh trúng cực cao."}
)

Write-Host "Count: $($nb.Count)"
